using V=BoundaryValue;using D=V::Dict;using A=V::Array;
Status shape(const FieldOrder& order,std::initializer_list<StableId> fields){if(order.empty())return common_success();std::set<StableId> wanted(fields);if(order.size()!=wanted.size())return common_failure("InvalidNavalNavigationFieldOrder");for(const auto& key:order)if(wanted.erase(key)!=1)return common_failure("InvalidNavalNavigationFieldOrder",key);return common_success();}
// The original JSON field writer is also the borrowed no-tree writer.
Status emit_value(ProjectionWriter& w,const StableId& key,const StableId& x){return w.field(key,x);}
Status emit_value(ProjectionWriter& w,const StableId& key,Integer x){return w.field(key,x);}
Status emit_value(ProjectionWriter& w,const StableId& key,bool x){return w.field(key,x);}
Status emit_value(ProjectionWriter& w,const StableId& key,const Owner& x){return emit_common_owner(w,key,x);}
Status emit_value(ProjectionWriter& w,const StableId& key,const Location& x){return emit_common_location(w,key,x);}
Status emit_value(ProjectionWriter& w,const StableId& key,const PointI& x){const std::array<Integer,2> point{x.x,x.y};return w.sequence(key,point,[](auto& c,Integer v){return c.field("",v);});}
Status emit_record_fields(ProjectionWriter&,const NavalVoyageVessel&);
Status emit_value(ProjectionWriter& w,const StableId& key,const NavalVoyageVessel& x){return w.object(key,[&](auto& c){return emit_record_fields(c,x);});}
Status emit_record_fields(ProjectionWriter&,const NavalVoyageFact&);
Status emit_value(ProjectionWriter& w,const StableId& key,const NavalVoyageFact& x){return w.object(key,[&](auto& c){return emit_record_fields(c,x);});}
Status emit_record_fields(ProjectionWriter&,const NavalNavigationVesselStep&);
Status emit_value(ProjectionWriter& w,const StableId& key,const NavalNavigationVesselStep& x){return w.object(key,[&](auto& c){return emit_record_fields(c,x);});}
Status emit_record_fields(ProjectionWriter&,const NavalNavigationStepFact&);
Status emit_value(ProjectionWriter& w,const StableId& key,const NavalNavigationStepFact& x){return w.object(key,[&](auto& c){return emit_record_fields(c,x);});}
Status emit_record_fields(ProjectionWriter&,const NavalNavigationState&);
Status emit_value(ProjectionWriter& w,const StableId& key,const NavalNavigationState& x){return w.object(key,[&](auto& c){return emit_record_fields(c,x);});}
template<class T>Status emit_value(ProjectionWriter& w,const StableId& key,const std::vector<T>& rows){return w.sequence(key,rows,[](auto& c,const auto& row){return emit_value(c,"",row);});}
template<class T>V projected_value(const T& value){V out;BoundaryProjectionWriter sink(out);auto checked=emit_value(sink,"",value);if(checked.ok)checked=sink.finish();if(!checked.ok)boundary::fail(checked.error.original.code,checked.error.original.path);return out;}

V enc(const StableId& x){return V{x};}V enc(Integer x){return V{x};}V enc(bool x){return V{x};}V enc(const Owner& x){return boundary::encode_owner(x);}V enc(PointI x){return V{A{V{x.x},V{x.y}}};}V enc(const Location& x){return boundary::encode_location(x);}
void dec(const V& v,StableId& x,const StableId& p){x=boundary::string(v,p);}void dec(const V& v,Integer& x,const StableId& p){x=boundary::integer(v,p);}void dec(const V& v,bool& x,const StableId& p){x=boundary::boolean(v,p);}void dec(const V& v,Owner& x,const StableId& p){x=boundary::decode_owner(v,p);}void dec(const V& v,Location& x,const StableId& p){x=boundary::decode_location(v,p);}void dec(const V& v,PointI& x,const StableId& p){const auto& a=boundary::array(v,p);if(a.size()!=2)boundary::fail("InvalidNavalNavigationPoint",p);x={boundary::integer(a[0],p),boundary::integer(a[1],p)};}
Status walk(CodecVisitor& c,StableId& x){return c.field("value",x);}Status walk(CodecVisitor& c,Integer& x){return c.field("value",x);}Status walk(CodecVisitor& c,bool& x){return c.field("value",x);}Status walk(CodecVisitor& c,Owner& x){return common_checkpoint::owner(c,x);}Status walk(CodecVisitor& c,Location& x){return common_checkpoint::location(c,x);}Status walk(CodecVisitor& c,PointI& x){c.field("x",x.x);return c.field("y",x.y);}
// 原Travel执行格式只在Naval5段内逐字段访问，不扩原Military的执行访客。
Status emit_execution_fields(ProjectionWriter& w,const TerrainExecution& r,const FieldOrder& order){auto check=shape(order,{"format","actor_id","action_id","plan_id","map_id","action_start_tick","source_tick","route_index_before","route_index_after","travel_credit_before","travel_credit_after","from_point","to_point","result_location"});if(!check.ok)return check;w.field("format",StableId{"HM-TERRAIN-EXECUTION/1"});emit_value(w,"actor_id",r.actor_id);emit_value(w,"action_id",r.action_id);emit_value(w,"plan_id",r.plan_id);emit_value(w,"map_id",r.map_id);emit_value(w,"action_start_tick",r.action_start_tick);emit_value(w,"source_tick",r.source_tick);emit_value(w,"route_index_before",r.route_index_before);emit_value(w,"route_index_after",r.route_index_after);emit_value(w,"travel_credit_before",r.travel_credit_before);emit_value(w,"travel_credit_after",r.travel_credit_after);emit_value(w,"from_point",r.from_point);emit_value(w,"to_point",r.to_point);emit_value(w,"result_location",r.result_location);w.order_fields(order);return w.status();}
void dec_e(const V& v,TerrainExecution& r,FieldOrder& order,const StableId& p){boundary::fields(v,{"format","actor_id","action_id","plan_id","map_id","action_start_tick","source_tick","route_index_before","route_index_after","travel_credit_before","travel_credit_after","from_point","to_point","result_location"},{},p);if(boundary::get_string(v,"format",p)!="HM-TERRAIN-EXECUTION/1")boundary::fail("InvalidNavalNavigationExecution",p);order=boundary::order(v);dec(boundary::field(v,"actor_id",p),r.actor_id,p+"/actor_id");dec(boundary::field(v,"action_id",p),r.action_id,p+"/action_id");dec(boundary::field(v,"plan_id",p),r.plan_id,p+"/plan_id");dec(boundary::field(v,"map_id",p),r.map_id,p+"/map_id");dec(boundary::field(v,"action_start_tick",p),r.action_start_tick,p+"/action_start_tick");dec(boundary::field(v,"source_tick",p),r.source_tick,p+"/source_tick");dec(boundary::field(v,"route_index_before",p),r.route_index_before,p+"/route_index_before");dec(boundary::field(v,"route_index_after",p),r.route_index_after,p+"/route_index_after");dec(boundary::field(v,"travel_credit_before",p),r.travel_credit_before,p+"/travel_credit_before");dec(boundary::field(v,"travel_credit_after",p),r.travel_credit_after,p+"/travel_credit_after");dec(boundary::field(v,"from_point",p),r.from_point,p+"/from_point");dec(boundary::field(v,"to_point",p),r.to_point,p+"/to_point");dec(boundary::field(v,"result_location",p),r.result_location,p+"/result_location");}
Status walk_e(CodecVisitor& c,TerrainExecution& r,FieldOrder& order){c.object("actor_id",[&](auto& v){return walk(v,r.actor_id);});c.object("action_id",[&](auto& v){return walk(v,r.action_id);});c.object("plan_id",[&](auto& v){return walk(v,r.plan_id);});c.object("map_id",[&](auto& v){return walk(v,r.map_id);});c.object("action_start_tick",[&](auto& v){return walk(v,r.action_start_tick);});c.object("source_tick",[&](auto& v){return walk(v,r.source_tick);});c.object("route_index_before",[&](auto& v){return walk(v,r.route_index_before);});c.object("route_index_after",[&](auto& v){return walk(v,r.route_index_after);});c.object("travel_credit_before",[&](auto& v){return walk(v,r.travel_credit_before);});c.object("travel_credit_after",[&](auto& v){return walk(v,r.travel_credit_after);});c.object("from_point",[&](auto& v){return walk(v,r.from_point);});c.object("to_point",[&](auto& v){return walk(v,r.to_point);});c.object("result_location",[&](auto& v){return walk(v,r.result_location);});common_checkpoint::strings(c,"field_order",order);if(!c.status().ok)return c.status();auto checked=shape(order,{"format","actor_id","action_id","plan_id","map_id","action_start_tick","source_tick","route_index_before","route_index_after","travel_credit_before","travel_credit_after","from_point","to_point","result_location"});return checked.ok?c.status():c.reject(checked.error.original.code);}
V enc(const NavalVoyageVessel&);void dec(const V&,NavalVoyageVessel&,const StableId&);Status walk(CodecVisitor&,NavalVoyageVessel&);
V enc(const NavalVoyageFact&);void dec(const V&,NavalVoyageFact&,const StableId&);Status walk(CodecVisitor&,NavalVoyageFact&);
V enc(const NavalNavigationVesselStep&);void dec(const V&,NavalNavigationVesselStep&,const StableId&);Status walk(CodecVisitor&,NavalNavigationVesselStep&);
V enc(const NavalNavigationStepFact&);void dec(const V&,NavalNavigationStepFact&,const StableId&);Status walk(CodecVisitor&,NavalNavigationStepFact&);
V enc(const NavalNavigationState&);void dec(const V&,NavalNavigationState&,const StableId&);Status walk(CodecVisitor&,NavalNavigationState&);
template<class T>V enc(const std::vector<T>& x){A a;for(const auto& item:x)a.push_back(enc(item));return V{std::move(a)};}
template<class T>void dec(const V& v,std::vector<T>& x,const StableId& p){for(const auto& item:boundary::array(v,p)){T row;dec(item,row,p);x.push_back(std::move(row));}}
template<class T>Status walk(CodecVisitor& c,std::vector<T>& x){return c.sequence("rows",x,[&](auto& child,auto& item){return walk(child,item);});}
// NavalVoyageVessel拒绝缺字段/附加字段；精确来源由同一原资产历史重放再次核对。
Status emit_record_fields(ProjectionWriter& w,const NavalVoyageVessel& r){auto check=shape(r.field_order,{"vessel_id","unit_id","captain_actor_id","owner","integrity"});if(!check.ok)return check;emit_value(w,"vessel_id",r.vessel_id);emit_value(w,"unit_id",r.unit_id);emit_value(w,"captain_actor_id",r.captain_actor_id);emit_value(w,"owner",r.owner);emit_value(w,"integrity",r.integrity);w.order_fields(r.field_order);return w.status();}
V enc(const NavalVoyageVessel& r){return projected_value(r);}
void dec(const V& v,NavalVoyageVessel& r,const StableId& p){boundary::fields(v,{"vessel_id","unit_id","captain_actor_id","owner","integrity"},{},p);r.field_order=boundary::order(v);dec(boundary::field(v,"vessel_id",p),r.vessel_id,p+"/vessel_id");dec(boundary::field(v,"unit_id",p),r.unit_id,p+"/unit_id");dec(boundary::field(v,"captain_actor_id",p),r.captain_actor_id,p+"/captain_actor_id");dec(boundary::field(v,"owner",p),r.owner,p+"/owner");dec(boundary::field(v,"integrity",p),r.integrity,p+"/integrity");}
Status walk(CodecVisitor& c,NavalVoyageVessel& r){c.object("vessel_id",[&](auto& v){return walk(v,r.vessel_id);});c.object("unit_id",[&](auto& v){return walk(v,r.unit_id);});c.object("captain_actor_id",[&](auto& v){return walk(v,r.captain_actor_id);});c.object("owner",[&](auto& v){return walk(v,r.owner);});c.object("integrity",[&](auto& v){return walk(v,r.integrity);});common_checkpoint::strings(c,"field_order",r.field_order);if(!c.status().ok)return c.status();auto check=shape(r.field_order,{"vessel_id","unit_id","captain_actor_id","owner","integrity"});return check.ok?c.status():c.reject(check.error.original.code);}
