Status emit_record_fields(ProjectionWriter& w,const NavalNavigationVesselStep& r){auto check=shape(r.field_order,{"vessel_id","previous_step_id","completed_before","completed_after","integrity_before","integrity_after"});if(!check.ok)return check;emit_value(w,"vessel_id",r.vessel_id);emit_value(w,"previous_step_id",r.previous_step_id);emit_value(w,"completed_before",r.completed_before);emit_value(w,"completed_after",r.completed_after);emit_value(w,"integrity_before",r.integrity_before);emit_value(w,"integrity_after",r.integrity_after);w.order_fields(r.field_order);return w.status();}
